out = []
for pid, name, cat, url, ex_codes, ex_sigs, nf_codes, nf_sigs in platforms:
    out.append({
        "platform_id": pid.lower(),
        "name": name,
        "category": cat,
        "url_template": url,
        "exists_status_codes": ex_codes,
        "exists_body_signatures": ex_sigs,
        "not_found_status_codes": nf_codes,
        "not_found_body_signatures": nf_sigs,
    })

path = pathlib.Path("src/redloop/data/platforms.json")
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(json.dumps({"version": "2.0", "count": len(out), "platforms": out}, indent=2), encoding="utf-8")
print(f"Wrote {len(out)} platforms to {path}")

